\title{Integer Structures on the Hyperbolic Disk:\\ A Rigorous Foundation for Arithmetic on Curved Space}
\author{Aristotle}
\date{2026-07-02}

\begin{document}
\maketitle

\begin{abstract}
We develop a set of exact foundational results linking the two standard models of the hyperbolic plane---the upper half-plane and the Poincar\'e disk---with the arithmetic of integer lattices and the symmetries of the modular group. We prove that the Cayley transform $C(z) = (z-i)/(z+i)$ maps the upper half-plane bijectively onto the open unit disk, exhibiting an explicit two-sided inverse. We identify two explicit generators of the principal congruence subgroup $\Gamma(2) \subseteq \SL(2,\ZZ)$ and show that the $\Gamma(2)$-orbit relation on the integer lattice $\ZZ^2$ is an equivalence relation. We establish discreteness of the lattice by proving that every Euclidean ball contains only finitely many lattice points. On the imaginary axis we analyze the hyperbolic midpoint, proving it is the geometric mean, that it is equidistant from its endpoints, commutative and idempotent, but not associative---an exact fingerprint of curvature. Finally, we prove the projective invariance of the cross-ratio under all M\"obius transformations. Together these results form a rigorous first floor for a program of ``number theory on curved space.''
\end{abstract}

\noindent\textbf{Keywords:} hyperbolic geometry, Poincar\'e disk, Cayley transform, modular group, congruence subgroup, cross-ratio, geometric mean, lattice discreteness, M\"obius transformation.

\section{Introduction}

The integers $\ZZ$ are usually pictured on a flat, straight line. Yet many of the richest structures in modern mathematics arise when arithmetic is transported onto a \emph{curved} stage. The hyperbolic plane is the archetype of such a stage: a space of constant negative curvature whose isometry group is intimately bound up with the modular group $\SL(2,\ZZ)$.

We work with the two standard conformal models of the hyperbolic plane: the upper half-plane $\HH = \{ z \in \CC : \im z > 0 \}$ and the Poincar\'e disk $\DD = \{ w \in \CC : |w| < 1 \}$. Our contributions are six exact results: (1) the Cayley transform is an explicit bijection $\HH \to \DD$; (2) two explicit generators of $\Gamma(2)$; (3) the $\Gamma(2)$-orbit relation on $\ZZ^2$ is an equivalence relation; (4) lattice discreteness; (5) the hyperbolic midpoint is the geometric mean and is equidistant, commutative, idempotent, but not associative; and (6) cross-ratio invariance.

\section{The Cayley Transform}

\begin{definition}[Cayley transform]
The \emph{Cayley transform} is $C(z) = \dfrac{z - i}{z + i}$.
\end{definition}

\begin{definition}[inverse Cayley transform]
The \emph{inverse Cayley transform} is $C^{-1}(w) = \dfrac{i\,(1 + w)}{1 - w}$.
\end{definition}

\begin{theorem}[image in the disk]
If $\im z > 0$, then $|C(z)|^2 < 1$; that is, $C(z) \in \DD$.
\end{theorem}
\begin{proof}[Proof sketch]
Write $z = x + iy$ with $y > 0$. Then $|z-i|^2 = x^2 + (y-1)^2$ and $|z+i|^2 = x^2 + (y+1)^2$, so
\[ |z+i|^2 - |z-i|^2 = (y+1)^2 - (y-1)^2 = 4y > 0. \]
Hence $|C(z)|^2 = |z-i|^2/|z+i|^2 < 1$. Geometrically, a point above the real axis is strictly closer to $i$ than to $-i$.
\end{proof}

\begin{theorem}[left inverse]
For every $z \neq -i$, $C^{-1}(C(z)) = z$.
\end{theorem}
\begin{theorem}[right inverse]
For every $w \neq 1$, $C(C^{-1}(w)) = w$.
\end{theorem}
\begin{proof}[Proof sketch]
Both are direct computations valid away from the pole of each map. For the left inverse,
\[ C^{-1}(C(z)) = i \cdot \frac{1 + \frac{z-i}{z+i}}{1 - \frac{z-i}{z+i}} = i \cdot \frac{(z+i) + (z-i)}{(z+i) - (z-i)} = i \cdot \frac{2z}{2i} = z, \]
valid for $z \neq -i$. The right inverse is symmetric and valid for $w \neq 1$.
\end{proof}

\begin{remark}
The excluded points $z=-i$ and $w=1$ are the poles corresponding to the point at infinity. Restricted to $\HH$ and $\DD$, $C$ is a conformal bijection, so hyperbolic-geometric statements transport freely between the two models.
\end{remark}

\section{Generators of the Congruence Subgroup $\Gamma(2)$}

For a positive integer $N$, the principal congruence subgroup of level $N$ is $\Gamma(N) = \{ g \in \SL(2,\ZZ) : g \equiv I \pmod{N} \}$.

\begin{definition}
Let $T = \begin{pmatrix} 1 & 2 \\ 0 & 1 \end{pmatrix}$ and $S = \begin{pmatrix} 1 & 0 \\ 2 & 1 \end{pmatrix}$.
\end{definition}

\begin{theorem}[membership]
Both $T$ and $S$ belong to $\Gamma(2)$.
\end{theorem}
\begin{proof}[Proof sketch]
Each has determinant $1\cdot 1 - 2\cdot 0 = 1$, so both lie in $\SL(2,\ZZ)$. Reducing modulo $2$, the off-diagonal entries $2 \equiv 0$ and the diagonal entries equal $1$, so both reduce to the identity; hence each lies in $\Gamma(2)$.
\end{proof}

\section{The $\Gamma(2)$-Orbit Relation on $\ZZ^2$}

\begin{definition}[orbit relation]
For $v, w \in \ZZ^2$, write $v \sim w$ iff there exists $g \in \Gamma(2)$ with $g\,v = w$.
\end{definition}

\begin{theorem}
The relation $\sim$ is reflexive, symmetric, and transitive.
\end{theorem}
\begin{proof}[Proof sketch]
\emph{Reflexivity:} $I \in \Gamma(2)$ and $Iv=v$. \emph{Symmetry:} if $gv=w$ then $g^{-1} \in \Gamma(2)$ and $g^{-1}w=v$; for $g=\left(\begin{smallmatrix} a&b\\ c&d\end{smallmatrix}\right)$ the inverse $\left(\begin{smallmatrix} d&-b\\ -c&a\end{smallmatrix}\right)$ is again $\equiv I \pmod 2$. \emph{Transitivity:} if $g_1v=w$ and $g_2w=u$ then $g_2g_1 \in \Gamma(2)$ and $(g_2g_1)v=u$. All three inherit from the group axioms.
\end{proof}

\section{Discreteness of the Lattice}

\begin{theorem}[finiteness in balls]
For every center $c=(c_1,c_2) \in \RR^2$ and radius $R \in \RR$, the set
\[ \{ (m,n) \in \ZZ^2 : (m-c_1)^2 + (n-c_2)^2 < R^2 \} \]
is finite.
\end{theorem}
\begin{proof}[Proof sketch]
If $(m,n)$ lies in the ball then $(m-c_1)^2 < R^2$ and $(n-c_2)^2 < R^2$, so $c_1-|R| < m < c_1+|R|$ and $c_2-|R| < n < c_2+|R|$. Each coordinate ranges over the integers in a bounded interval, of which there are finitely many; the set embeds in a finite product and is therefore finite.
\end{proof}

\begin{corollary}
Every $\Gamma(2)$-orbit meets any bounded region in a finite set, so orbits are discrete and lattice-point counting in a growing hyperbolic disk is well posed.
\end{corollary}

\section{The Hyperbolic Midpoint on the Imaginary Axis}

We represent the point $is \in \HH$ (with $s>0$) by the positive real $s$.

\begin{definition}[hyperbolic distance]
For $a,b>0$, $\; d(a,b) = |\log(a/b)|$.
\end{definition}
\begin{definition}[hyperbolic midpoint]
For $s,t>0$, $\; m(s,t) = \sqrt{s\,t}$.
\end{definition}

\begin{theorem}[equidistance]
For $s,t>0$, $\; d(s, m(s,t)) = d(m(s,t), t)$.
\end{theorem}
\begin{proof}[Proof sketch]
Both equal $\tfrac12|\log(s/t)|$, since $\log(s/\sqrt{st}) = \tfrac12\log(s/t)$ and $\log(\sqrt{st}/t) = \tfrac12\log(s/t)$.
\end{proof}

\begin{theorem}[commutativity]
$m(s,t)=m(t,s)$.
\end{theorem}
\begin{theorem}[idempotence]
For $s \ge 0$, $\; m(s,s)=s$.
\end{theorem}
\begin{theorem}[non-associativity]
There exist $s,t,u>0$ with $m(m(s,t),u) \neq m(s,m(t,u))$.
\end{theorem}
\begin{proof}
Take $s=t=1$, $u=16$: then $m(m(1,1),16)=m(1,16)=4$, while $m(1,m(1,16))=m(1,4)=2$, and $4 \neq 2$.
\end{proof}

\begin{remark}
In additive coordinates $x=\log s$ the midpoint is the ordinary average, which is commutative and idempotent but non-associative as a binary mean; the geometric mean inherits this. Non-associativity is the correct signature of a genuine metric midpoint operation.
\end{remark}

\section{Invariance of the Cross-Ratio}

\begin{definition}[cross-ratio]
For distinct $z_1,z_2,z_3,z_4 \in \CC$,
\[ (z_1,z_2;z_3,z_4) = \frac{(z_1-z_3)(z_2-z_4)}{(z_1-z_4)(z_2-z_3)}. \]
\end{definition}
\begin{definition}[M\"obius transformation]
$\mu(z) = \dfrac{az+b}{cz+d}$.
\end{definition}

\begin{theorem}[cross-ratio invariance]
Let $\mu(z)=(az+b)/(cz+d)$ with $ad-bc \neq 0$. Assume $cz_k+d \neq 0$ for each $k$ and $z_1-z_4 \neq 0$, $z_2-z_3 \neq 0$. Then
\[ (\mu(z_1),\mu(z_2);\mu(z_3),\mu(z_4)) = (z_1,z_2;z_3,z_4). \]
\end{theorem}
\begin{proof}[Proof sketch]
The key identity is
\[ \mu(z_i)-\mu(z_j) = \frac{(ad-bc)(z_i-z_j)}{(cz_i+d)(cz_j+d)}. \]
Substituting into the cross-ratio, numerator and denominator each acquire the same factor $(ad-bc)^2$ and the same product of four linear denominators; all cancel, leaving the original cross-ratio.
\end{proof}

\begin{remark}
Since real M\"obius transformations of positive determinant are the orientation-preserving isometries of $\HH$, the cross-ratio is an isometry invariant from which hyperbolic distance can be reconstructed.
\end{remark}

\section{Discussion}

These foundational results make the two hyperbolic models interchangeable, equip the integer lattice with the modular symmetry $\Gamma(2)$ and organize it into discrete orbit classes, and expose the geometric personality of arithmetic on curved space. We distinguish the proven from the aspirational: the sweeping vision of hyperbolic primes, a hyperbolic prime number theorem, and a hyperbolic zeta function remains conjectural. What is established is the exact scaffolding on which such a program could be built.

\section{Future Directions}

Building on this foundation, several concrete directions emerge, centered on the Farey tessellation whose vertices are the reduced fractions, with an edge joining $p/q$ and $r/s$ exactly when $|ps-qr|=1$.

\begin{enumerate}
\item \textbf{The golden ratio as the slowest-escaping cusp.} Among geodesic rays that leave every bounded region, the Fibonacci ray toward the golden ratio appears to make the fewest turns per unit of denominator growth; the all-ones continued fraction $[1;1,1,\dots]$ is the unique walk that never accelerates, conjecturally characterizing the golden ratio as the most central boundary point.
\item \textbf{Determinant depth equals continued-fraction length.} Graph distance in the Farey tessellation is conjectured to equal the sum of partial quotients of the relevant continued fraction, computed by the subtractive Euclidean algorithm, since each mediant step mirrors one subtraction step.
\item \textbf{A prime tessellation obstruction.} Restricting to fractions with prime denominator, the induced subgraph is conjectured connected only with a single extra ``jump'' per prime, the minimum number of jumps to reach denominator $q$ growing like the number of primes below $q$.
\end{enumerate}

\end{document}

