def cayley(z: complex) -> complex:
    return (z - 1j) / (z + 1j)

def inv_cayley(w: complex) -> complex:
    return 1j * (1 + w) / (1 - w)

for z in [1j, 2j, 1 + 1j, -3 + 0.5j, 10 + 4j]:
    w = cayley(z)
    assert abs(w) < 1
    assert abs(inv_cayley(w) - z) < 1e-9
    print(f"z={z} -> C(z)={w:.4f}  |C(z)|={abs(w):.4f}")

Mat = tuple  # (a, b, c, d)
T = (1, 2, 0, 1); S = (1, 0, 2, 1)

def det(m): a,b,c,d = m; return a*d - b*c
def in_gamma2(m):
    a,b,c,d = m
    return det(m) == 1 and (a%2,b%2,c%2,d%2) == (1,0,0,1)
def mul(p,q):
    a,b,c,d = p; e,f,g,h = q
    return (a*e+b*g, a*f+b*h, c*e+d*g, c*f+d*h)
def inv(m): a,b,c,d = m; return (d,-b,-c,a)
def act(m,v): a,b,c,d = m; x,y = v; return (a*x+b*y, c*x+d*y)

assert in_gamma2(T) and in_gamma2(S)
v = (1,0); g = mul(T,S)
assert act(inv(g), act(g,v)) == v                 # symmetry
assert act(S, act(T,v)) == act(mul(S,T), v)       # transitivity
print("Gamma(2) generators verified; orbit relation is an equivalence relation")

def cross_ratio(z1, z2, z3, z4):
    return ((z1 - z3) * (z2 - z4)) / ((z1 - z4) * (z2 - z3))

def mobius(a, b, c, d, z):
    return (a * z + b) / (c * z + d)

pts = (0+0j, 1+0j, 2+1j, -1+3j)
a, b, c, d = (2+1j, -1+0j, 1+0j, 3-1j)
assert abs(a*d - b*c) > 1e-9
orig  = cross_ratio(*pts)
moved = cross_ratio(*(mobius(a, b, c, d, z) for z in pts))
assert abs(orig - moved) < 1e-9
print(f"original={orig:.6f}  moebius={moved:.6f}  invariant")

